with lines as (select id, plan, currency, val from price_tiers lateral view explode(discounts) li as val), enriched as (select *, min(val) over (partition by plan) as plan_min_val, dense_rank() over (partition by plan, currency order by val desc nulls last) as val_dense_rank, cume_dist() over (order by val desc nulls last) as val_cume_dist, max(val) over (partition by plan) as plan_max_val from lines where plan = 'basic'), metrics as (select *, cume_dist() over (partition by plan order by plan_min_val desc nulls first) as plan_min_val_cume_dist, dense_rank() over (order by plan_min_val desc nulls first) as plan_min_val_dense_rank, percent_rank() over w_part as plan_max_val_percent_rank from enriched window w_part as (partition by currency order by plan_max_val desc)), base as (select *, cast(val as int) as val_int from metrics where plan = 'enterprise') select case when plan_min_val_cume_dist >= 0.81 then 'HIGH' else 'LOW' end as plan_min_val_cume_dist_tier, case when plan_max_val_percent_rank >= 0.86 then 'HIGH' else 'LOW' end as plan_max_val_percent_rank_tier, approx_percentile(plan_min_val_dense_rank, 0.5) as plan_min_val_dense_rank_p50, count(*) filter (where plan = 'basic') as basic_rows, size(collect_set(currency)) as num_currencies, sum(val_cume_dist) as total_val_cume_dist, sum(plan_min_val) as total_plan_min_val, approx_percentile(val_dense_rank, array(0.25, 0.5, 0.75)) as val_dense_rank_quartiles from base group by plan_min_val_cume_dist_tier, plan_max_val_percent_rank_tier order by plan_min_val_cume_dist_tier desc nulls last
